    private const int DefaultErrorLimit = 20;

    [Parameter, EditorRequired]
    public string TenantId { get; set; } = string.Empty;

    [Parameter, EditorRequired]
    public string ProjectionName { get; set; } = string.Empty;

    [Parameter]
    public EventCallback OnClose { get; set; }

    private ProjectionDetail? _detail;
    private bool _isLoading = true;
    private bool _showAllErrors;
    private bool _isOperating;
    private string? _operatingAction;

    // P4: Change detection for OnParametersSetAsync
    private string? _prevTenantId;
    private string? _prevProjectionName;

    // P2: Reset dialog state
    private bool _showResetDialog;
    private bool _pendingShowReset;
    private FluentDialog? _resetDialog;
    private long? _resetFromPosition;
    private string? _resetInitiatorId;

    // P1: Replay dialog state
    private bool _showReplayDialog;
    private bool _pendingShowReplay;
    private FluentDialog? _replayDialog;
    private long? _replayFromPosition;
    private long? _replayToPosition;
    private string? _replayValidationError;
    private string? _replayInitiatorId;

    protected override async Task OnParametersSetAsync()
    {
        // P4: Skip reload if parameters haven't changed
        if (TenantId == _prevTenantId && ProjectionName == _prevProjectionName)
        {
            return;
        }

        _prevTenantId = TenantId;
        _prevProjectionName = ProjectionName;

        if (!string.IsNullOrEmpty(TenantId) && !string.IsNullOrEmpty(ProjectionName))
        {
            await LoadDetailAsync().ConfigureAwait(false);
        }
    }

    private async Task LoadDetailAsync()
    {
        _isLoading = true;
        _showAllErrors = false;

        try
        {
            _detail = await ApiClient.GetProjectionDetailAsync(TenantId, ProjectionName).ConfigureAwait(false);
            if (_detail is null)
            {
                await ToastService.ShowWarningAsync("Projection not found");
                await OnClose.InvokeAsync().ConfigureAwait(false);
            }
        }
        catch (Exception)
        {
            _detail = null;
        }
        finally
        {
            _isLoading = false;
        }
    }

    private IQueryable<ProjectionError> GetDisplayedErrors()
    {
        if (_detail is null)
        {
            return Array.Empty<ProjectionError>().AsQueryable();
        }

        IEnumerable<ProjectionError> errors = _detail.Errors.OrderByDescending(e => e.Timestamp);
        if (!_showAllErrors && _detail.Errors.Count > DefaultErrorLimit)
        {
            errors = errors.Take(DefaultErrorLimit);
        }

        return errors.AsQueryable();
    }

    private async Task OnPauseClick()
    {
        await ExecuteOperationAsync("pause", async () =>
        {
            DialogResult result = await DialogService.ShowConfirmationAsync(
                $"Are you sure you want to pause projection '{_detail!.Name}'?",
                "Confirm Pause",
                "Pause",
                "Cancel").ConfigureAwait(false);
            if (result.Cancelled)
            {
                return;
            }

            AdminOperationResult? opResult = await ApiClient
                .PauseProjectionAsync(TenantId, ProjectionName)
                .ConfigureAwait(false);
            if (opResult?.Success == true)
            {
                await ToastService.ShowSuccessAsync("Projection paused successfully");
            }
            else
            {
                await ToastService.ShowErrorAsync("Failed to pause projection");
            }

            await Task.Delay(500).ConfigureAwait(false);
            await LoadDetailAsync().ConfigureAwait(false);
        }).ConfigureAwait(false);
    }

    private async Task OnResumeClick()
    {
        await ExecuteOperationAsync("resume", async () =>
        {
            DialogResult result = await DialogService.ShowConfirmationAsync(
                $"Are you sure you want to resume projection '{_detail!.Name}'?",
                "Confirm Resume",
                "Resume",
                "Cancel").ConfigureAwait(false);
            if (result.Cancelled)
            {
                return;
            }

            AdminOperationResult? opResult = await ApiClient
                .ResumeProjectionAsync(TenantId, ProjectionName)
                .ConfigureAwait(false);
            if (opResult?.Success == true)
            {
                await ToastService.ShowSuccessAsync("Projection resumed successfully");
            }
            else
            {
                await ToastService.ShowErrorAsync("Failed to resume projection");
            }

            await Task.Delay(500).ConfigureAwait(false);
            await LoadDetailAsync().ConfigureAwait(false);
        }).ConfigureAwait(false);
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (_pendingShowReset && _resetDialog is not null)
        {
            await _resetDialog.ShowAsync().ConfigureAwait(false);
            _pendingShowReset = false;
        }

        if (_pendingShowReplay && _replayDialog is not null)
        {
            await _replayDialog.ShowAsync().ConfigureAwait(false);
            _pendingShowReplay = false;
        }
    }

    // P2: Reset dialog with From Position input and danger confirm
    private void ShowResetDialog()
    {
        _resetFromPosition = null;
        _resetInitiatorId = "projection-reset-button";
        _showResetDialog = true;
        _pendingShowReset = true;
    }

    private async Task CancelResetDialogAsync()
    {
        if (_resetDialog is not null)
        {
            await _resetDialog.HideAsync().ConfigureAwait(false);
        }

        _showResetDialog = false;
        string? focusId = _resetInitiatorId;
        _resetInitiatorId = null;
        await InvokeAsync(StateHasChanged).ConfigureAwait(false);
        await FocusService.RestoreAsync(focusId).ConfigureAwait(false);
    }

    private async Task ConfirmResetAsync()
    {
        if (_detail is null)
        {
            return;
        }

        string confirmationTarget = Text["ProjectionTarget", ProjectionName, TenantId];
        if (!ConfirmationFacts.IsExactAndSupportSafe(confirmationTarget))
        {
            await ToastService.ShowErrorAsync(Text["ConfirmationUnsafeTarget"]).ConfigureAwait(false);
            await CloseResetDialogAndRestoreFocusAsync().ConfigureAwait(false);
            return;
        }

        if (_resetFromPosition is < 0)
        {
            await FailResetValidationAsync("From Position must be non-negative.").ConfigureAwait(false);
            return;
        }

        _isOperating = true;
        _operatingAction = "reset";

        AdminOperationResult? opResult;
        try
        {
            opResult = await ApiClient
                .ResetProjectionAsync(TenantId, ProjectionName, _resetFromPosition)
                .ConfigureAwait(false);
        }
        catch (UnauthorizedAccessException)
        {
            _isOperating = false;
            _operatingAction = null;
            await ToastService.ShowErrorAsync("Unauthorized").ConfigureAwait(false);
            await CloseResetDialogAndRestoreFocusAsync().ConfigureAwait(false);
            return;
        }
        catch (ForbiddenAccessException)
        {
            _isOperating = false;
            _operatingAction = null;
            await ToastService.ShowErrorAsync("Forbidden — insufficient permissions").ConfigureAwait(false);
            await CloseResetDialogAndRestoreFocusAsync().ConfigureAwait(false);
            return;
        }
        catch (ServiceUnavailableException)
        {
            await ToastService.ShowErrorAsync("Service unavailable — try again later").ConfigureAwait(false);
            _isOperating = false;
            _operatingAction = null;
            return;
        }
        catch (Exception ex)
        {
            _ = ex;
            // Re-enable the initiating control before focus moves back to it.
            _isOperating = false;
            _operatingAction = null;
            await ToastService.ShowErrorAsync("Projection operation failed. Refresh status before deciding whether to retry.").ConfigureAwait(false);
            await CloseResetDialogAndRestoreFocusAsync().ConfigureAwait(false);
            return;
        }

        if (opResult?.Success != true)
        {
            _isOperating = false;
            _operatingAction = null;
            await ToastService.ShowErrorAsync("Failed to reset projection").ConfigureAwait(false);
            await CloseResetDialogAndRestoreFocusAsync().ConfigureAwait(false);
            return;
        }

        try
        {
            await ToastService.ShowSuccessAsync($"Reset request accepted (Operation: {opResult.OperationId})").ConfigureAwait(false);
            if (_resetDialog is not null)
            {
                await _resetDialog.HideAsync().ConfigureAwait(false);
            }

            _showResetDialog = false;
            await PollForUpdateAsync().ConfigureAwait(false);
        }
        catch (Exception)
        {
            _showResetDialog = false;
            await InvokeAsync(StateHasChanged).ConfigureAwait(false);
            await ToastService.ShowInfoAsync("Reset request was accepted, but status refresh failed. Refresh the projection before deciding whether to retry.").ConfigureAwait(false);
        }

        _isOperating = false;
        _operatingAction = null;
    }

    // P1: Replay dialog with From/To inputs and validation
    private void ShowReplayDialog()
    {
        _replayFromPosition = 0;
        _replayToPosition = _detail?.LastProcessedPosition;
        _replayValidationError = null;
        _replayInitiatorId = "projection-replay-button";
        _showReplayDialog = true;
        _pendingShowReplay = true;
    }

    private async Task CancelReplayDialogAsync()
    {
        if (_replayDialog is not null)
        {
            await _replayDialog.HideAsync().ConfigureAwait(false);
        }

        _showReplayDialog = false;
        _replayValidationError = null;
        string? focusId = _replayInitiatorId;
        _replayInitiatorId = null;
        await InvokeAsync(StateHasChanged).ConfigureAwait(false);
        await FocusService.RestoreAsync(focusId).ConfigureAwait(false);
    }

    private async Task ConfirmReplayAsync()
    {
        if (_detail is null)
        {
            return;
        }

        string confirmationTarget = Text["ProjectionTarget", ProjectionName, TenantId];
        if (!ConfirmationFacts.IsExactAndSupportSafe(confirmationTarget))
        {
            await ToastService.ShowErrorAsync(Text["ConfirmationUnsafeTarget"]).ConfigureAwait(false);
            await CloseReplayDialogAndRestoreFocusAsync().ConfigureAwait(false);
            return;
        }

        // P1: Validate From < To (strictly less than)
        _replayValidationError = null;
        if (_replayFromPosition is null)
        {
            await FailReplayValidationAsync("From Position is required.").ConfigureAwait(false);
            return;
        }

        if (_replayToPosition is null)
        {
            await FailReplayValidationAsync("To Position is required.").ConfigureAwait(false);
            return;
        }

        if (_replayFromPosition.Value < 0 || _replayToPosition.Value < 0)
        {
            await FailReplayValidationAsync("Replay positions must be non-negative.").ConfigureAwait(false);
            return;
        }

        if (_replayFromPosition.Value >= _replayToPosition.Value)
        {
            await FailReplayValidationAsync("From Position must be strictly less than To Position.").ConfigureAwait(false);
            return;
        }

        _isOperating = true;
        _operatingAction = "replay";

        AdminOperationResult? opResult;
        try
        {
            opResult = await ApiClient
                .ReplayProjectionAsync(TenantId, ProjectionName, _replayFromPosition.Value, _replayToPosition.Value)
                .ConfigureAwait(false);
        }
        catch (UnauthorizedAccessException)
        {
            _isOperating = false;
            _operatingAction = null;
            await ToastService.ShowErrorAsync("Unauthorized").ConfigureAwait(false);
            await CloseReplayDialogAndRestoreFocusAsync().ConfigureAwait(false);
            return;
        }
        catch (ForbiddenAccessException)
        {
            _isOperating = false;
            _operatingAction = null;
            await ToastService.ShowErrorAsync("Forbidden — insufficient permissions").ConfigureAwait(false);
            await CloseReplayDialogAndRestoreFocusAsync().ConfigureAwait(false);
            return;
        }
        catch (ServiceUnavailableException)
        {
            await ToastService.ShowErrorAsync("Service unavailable — try again later").ConfigureAwait(false);
            _isOperating = false;
            _operatingAction = null;
            return;
        }
        catch (Exception ex)
        {
            _ = ex;
            // Re-enable the initiating control before focus moves back to it.
            _isOperating = false;
            _operatingAction = null;
            await ToastService.ShowErrorAsync("Projection operation failed. Refresh status before deciding whether to retry.").ConfigureAwait(false);
            await CloseReplayDialogAndRestoreFocusAsync().ConfigureAwait(false);
            return;
        }

        if (opResult?.Success != true)
        {
            _isOperating = false;
            _operatingAction = null;
            await ToastService.ShowErrorAsync("Failed to replay projection").ConfigureAwait(false);
            await CloseReplayDialogAndRestoreFocusAsync().ConfigureAwait(false);
            return;
        }

        try
        {
            await ToastService.ShowSuccessAsync($"Replay request accepted (Operation: {opResult.OperationId})").ConfigureAwait(false);
            if (_replayDialog is not null)
            {
                await _replayDialog.HideAsync().ConfigureAwait(false);
            }

            _showReplayDialog = false;
            await PollForUpdateAsync().ConfigureAwait(false);
        }
        catch (Exception)
        {
            _showReplayDialog = false;
            await InvokeAsync(StateHasChanged).ConfigureAwait(false);
            await ToastService.ShowInfoAsync("Replay request was accepted, but status refresh failed. Refresh the projection before deciding whether to retry.").ConfigureAwait(false);
        }

        _isOperating = false;
        _operatingAction = null;
    }

    private async Task CloseResetDialogAndRestoreFocusAsync()
    {
        if (_resetDialog is not null)
        {
            await _resetDialog.HideAsync().ConfigureAwait(false);
        }

        _showResetDialog = false;
        string? focusId = _resetInitiatorId;
        _resetInitiatorId = null;
        await InvokeAsync(StateHasChanged).ConfigureAwait(false);
        await FocusService.RestoreAsync(focusId).ConfigureAwait(false);
    }

    private async Task CloseReplayDialogAndRestoreFocusAsync()
    {
        if (_replayDialog is not null)
        {
            await _replayDialog.HideAsync().ConfigureAwait(false);
        }

        _showReplayDialog = false;
        string? focusId = _replayInitiatorId;
        _replayInitiatorId = null;
        await InvokeAsync(StateHasChanged).ConfigureAwait(false);
        await FocusService.RestoreAsync(focusId).ConfigureAwait(false);
    }

    private async Task FailReplayValidationAsync(string message)
    {
        _replayValidationError = message;
        await ToastService.ShowErrorAsync(message).ConfigureAwait(false);
        await CloseReplayDialogAndRestoreFocusAsync().ConfigureAwait(false);
    }

    private async Task FailResetValidationAsync(string message)
    {
        await ToastService.ShowErrorAsync(message).ConfigureAwait(false);
        await CloseResetDialogAndRestoreFocusAsync().ConfigureAwait(false);
    }

    private async Task ExecuteOperationAsync(string action, Func<Task> operation)
    {
        _isOperating = true;
        _operatingAction = action;

        try
        {
            await operation().ConfigureAwait(false);
        }
        catch (UnauthorizedAccessException)
        {
            await ToastService.ShowErrorAsync("Unauthorized").ConfigureAwait(false);
        }
        catch (ForbiddenAccessException)
        {
            await ToastService.ShowErrorAsync("Forbidden — insufficient permissions").ConfigureAwait(false);
        }
        catch (ServiceUnavailableException)
        {
            await ToastService.ShowErrorAsync("Service unavailable — try again later").ConfigureAwait(false);
        }
        catch (Exception ex)
        {
            _ = ex;
            await ToastService.ShowErrorAsync("Projection operation failed. Refresh status before deciding whether to retry.").ConfigureAwait(false);
        }
        finally
        {
            _isOperating = false;
            _operatingAction = null;
        }
    }

    // P5: Poll without triggering OnClose on transient 404
    private async Task PollForUpdateAsync()
    {
        ProjectionStatusType? originalStatus = _detail?.Status;
        for (int i = 0; i < 3; i++)
        {
            await Task.Delay(1000).ConfigureAwait(false);
            ProjectionDetail? polledDetail = await ApiClient
                .GetProjectionDetailAsync(TenantId, ProjectionName)
                .ConfigureAwait(false);

            if (polledDetail is null)
            {
                // Temporarily unavailable during async operation — keep panel open
                continue;
            }

            _detail = polledDetail;
            _isLoading = false;
            if (_detail.Status != originalStatus)
            {
                return;
            }
        }

        await ToastService.ShowInfoAsync("Operation submitted — status may take a moment to update");
    }

    // P8: Boundary-safe relative time formatting
    private static string FormatRelativeTime(DateTimeOffset timestamp)
    {
        if (timestamp == DateTimeOffset.MinValue)
        {
            return "Never";
        }

        TimeSpan elapsed = DateTimeOffset.UtcNow - timestamp;
        if (elapsed < TimeSpan.Zero)
        {
            return "Just now";
        }

        if (elapsed.TotalSeconds < 60)
        {
            return $"{(int)elapsed.TotalSeconds}s ago";
        }

        if (elapsed.TotalMinutes < 60)
        {
            return $"{(int)elapsed.TotalMinutes}m ago";
        }

        if (elapsed.TotalHours < 24)
        {
            return $"{(int)elapsed.TotalHours}h ago";
        }

        return $"{(int)elapsed.TotalDays}d ago";
    }

